char carry = ' ';
char next = text_buffer[input_cursor];
char* slot = &text_buffer[input_cursor];
while (next != 0) {
    *slot = carry;
    ++slot;
    carry = next;
    next = *slot;
}
*slot = carry;
slot[1] = 0;

